/**
 * Port for binary file storage. The local driver is used today; an S3-compatible driver can be
 * added later as another implementation registered in `StorageModule`, without touching callers.
 */
export abstract class FileStorage {
  abstract put(key: string, data: Buffer, contentType: string): Promise<void>;
  abstract get(key: string): Promise<Buffer | null>;
  abstract delete(key: string): Promise<void>;
}

/** Keys are generated by the server only: `projects/<uuid>/<uuid>.webp`. */
export const STORAGE_KEY_PATTERN = /^projects\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.webp$/;
